import{_ as s,l as i,o as e,c as n,v as t,p as l,x as r,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"IPv6 对照","description":"","frontmatter":{"title":"IPv6 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ipv6-contrast.md","filePath":"cs/ipv6-contrast.md","lastUpdated":1789023840000}'),c={name:"cs/ipv6-contrast.md"};function A(h,a,_,T,v,C){const o=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="ipv6-对照" tabindex="-1">IPv6 对照 <a class="header-anchor" href="#ipv6-对照" aria-label="Permalink to &quot;IPv6 对照&quot;">​</a></h1><div class="epigraph"><p>IPv6 把地址加到 128 位，去掉头校验和与路由器分片；邻居发现取代 ARP。</p><footer>—— 据 Deering and Hinden, RFC 8200, Internet Protocol, Version 6, 2017 整理</footer></div><p><a href="/cs/napt">上一课</a>用租约与 NAT 缓解 IPv4 短缺。把 32 位拉长并清理头格式，是另一条路。缺口是<strong>对照</strong>：同一套<a href="/cs/layering-e2e">分层</a>与 <a href="/cs/lpm">LPM</a> 仍在，哪些 knobs 换了。本课不重写 CIDR 思想，不把全部扩展头类型背完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NAT 让大量主机挤在私网，入站连接与端到端校验变难。RFC 8200：128 位地址、固定 40 字节基本头、流标签、下一头字段链扩展头。路由器不分片，PMTU 交给源；无 IP 头校验和，交给链路与传输。缺口是这些与 RFC 791 的差异表，不是再讲一次掩码。</p><p>地址自动配置（SLAAC）与 ICMPv6 邻居发现替换 ARP，DHCP 变为可选。</p><p><span class="marginnote">教学对照：更大地址、无中间分片、ND 代替 ARP、仍是尽力而为。NAT64 等过渡机制是附录级，不插主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>转发仍 LPM，只是键为 128 位。主机：链路本地地址起步，路由器通告前缀，得全球地址。邻居请求/通告用组播，不再以太网广播 ARP。传输层端口语义不变，后课 TCP/UDP 仍用端口；套接字只是地址族变成 <code>AF_INET6</code>。</p>',9)),(e(),l(P,null,{default:r(()=>[d(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20V4%5B%22IPv4%3A%2032%20%E4%BD%8D%2C%20ARP%2C%20%E5%8F%AF%E5%88%86%E7%89%87%22%5D%20--%3E%20CONTRAST%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20V6%5B%22IPv6%3A%20128%20%E4%BD%8D%2C%20ND%2C%20%E6%BA%90%E4%BE%A7%20PMTU%22%5D%20--%3E%20CONTRAST%0A%20%20CONTRAST%20--%3E%20RT%5B%22%E8%B7%AF%E7%94%B1%E5%8D%8F%E8%AE%AE%E4%BB%8D%E5%A1%AB%20LPM%20%E8%A1%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>IPv6 把<a href="/cs/layering-e2e">端到端论证</a>里「地址应能命名端」的压力从 NAT 挪回地址空间。它不自动提供可靠性或拥塞控制。扩展头让 IPsec 等可插入，安全课再讲；本课不把加密当 IPv6 的定义特征——保密不是 RFC 8200 的必选项。</p><p>双栈主机两套表、两套默认路由，应用选族失败则试另一族，细节不展开。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把移动 IPv6、SHIM6 写进主干。不引入段路由扩展头的工程手册。也不声称「有 IPv6 就不再有 NAT」：运营上仍可能出现中间盒。控制平面如何在任意地址族上算下一跳，下一课从距离向量开始。</p><p>链路本地地址每条链路重复出现，转发表必须带着接口。全局地址才进默认路由那一套 LPM。</p><p>扩展头必须按顺序处理；未知的逐跳选项会让路由器丢包，这与 IPv4 选项一样是部署负担。</p><p>后课默认：转发对象可以是 v4 或 v6 前缀。表项从哪来，下一课距离向量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IPv6（RFC 8200）对照：更长地址、ND、不分片、无头校验和。</li><li>LPM 与尽力而为不变；不代替 TCP。</li><li>路由协议填表是下一课起的缺口。</li><li>出处：RFC 8200；RFC 791 对照；Kurose and Ross。</li></ul>',10))])}const I=s(c,[["render",A]]);export{m as __pageData,I as default};
